(function(){"use strict";self.onmessage=function(o){const{type:t,data:e}=o.data;switch(t){case"sample":d(e);break}};function d(o){const{spectrum:t,targetWidth:e,zoomX:l}=o;if(!t||t.length===0){self.postMessage({type:"sampled",data:{sampled:new Float32Array(0)}});return}if(!e||e<=0){self.postMessage({type:"sampled",data:{sampled:new Float32Array(t)}});return}const f=l?l[0]:0,i=l?l[1]:1,m=Math.floor(f*t.length),g=Math.ceil(i*t.length),s=t.slice(m,g);if(s.length<=e){self.postMessage({type:"sampled",data:{sampled:new Float32Array(s)}});return}const p=new Float32Array(e),c=s.length/e;for(let a=0;a<e;a++){const h=Math.floor(a*c),y=Math.floor((a+1)*c);let r=-1/0;for(let n=h;n<y&&n<s.length;n++)s[n]>r&&(r=s[n]);p[a]=r}self.postMessage({type:"sampled",data:{sampled:p}})}})();
